INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-20', 'es', 'LAIKA 64 3.3: en línea sin cuelgues', 'Las partidas largas en línea ya no congelan ni apagan la consola. Conexión directa más firme, chat sin tirones, el control ya no vibra solo mientras esperas y la pantalla ya no se oscurece. Actualiza desde LAIKA.'),
 ('2026-11-20', 'en', 'LAIKA 64 3.3: online play without hangs', 'Long online games no longer freeze or power off the console. Steadier direct connection, smooth chat, the controller no longer vibrates by itself while you wait and the screen no longer dims. Update from LAIKA.'),
 ('2026-11-20', 'pt', 'LAIKA 64 3.3: online sem travamentos', 'Partidas longas online não congelam nem desligam mais o console. Conexão direta mais firme, chat sem engasgos, o controle não vibra mais sozinho enquanto você espera e a tela não escurece mais. Atualize pelo LAIKA.'),
 ('2026-11-20', 'fr', 'LAIKA 64 3.3 : en ligne sans blocages', 'Les longues parties en ligne ne figent ni n''éteignent plus la console. Connexion directe plus solide, chat sans saccades, la manette ne vibre plus seule pendant l''attente et l''écran ne s''assombrit plus. Mettez à jour depuis LAIKA.'),
 ('2026-11-20', 'it', 'LAIKA 64 3.3: online senza blocchi', 'Le partite online lunghe non bloccano né spengono più la console. Connessione diretta più stabile, chat senza scatti, il controller non vibra più da solo mentre aspetti e lo schermo non si scurisce più. Aggiorna da LAIKA.'),
 ('2026-11-20', 'de', 'LAIKA 64 3.3: online ohne Hänger', 'Lange Online-Partien frieren die Konsole nicht mehr ein und schalten sie nicht aus. Stabilere Direktverbindung, Chat ohne Ruckeln, kein Vibrieren mehr beim Warten und der Bildschirm wird nicht mehr dunkel. Aktualisiere in LAIKA.'),
 ('2026-11-20', 'ru', 'LAIKA 64 3.3: онлайн без зависаний', 'Долгие онлайн-матчи больше не замораживают и не выключают консоль. Прямое соединение стабильнее, чат без рывков, контроллер не вибрирует сам во время ожидания, экран больше не темнеет. Обновитесь в LAIKA.'),
 ('2026-11-20', 'es', 'Apoya a LAIKA 64', 'LAIKA lo necesita: tu donación paga los servidores del juego en línea y las próximas actualizaciones. LAIKA 64 es y seguirá siendo gratis. Dona en paypal.me/ErickAbrahamA o en Juego en línea > Donar. ¡Gracias!'),
 ('2026-11-20', 'en', 'Support LAIKA 64', 'LAIKA needs it: your donation pays for the online servers and the next updates. LAIKA 64 is and will stay free. Donate at paypal.me/ErickAbrahamA or in Online play > Donate. Thank you!'),
 ('2026-11-20', 'pt', 'Apoie o LAIKA 64', 'O LAIKA precisa: sua doação paga os servidores do jogo online e as próximas atualizações. O LAIKA 64 é e continuará grátis. Doe em paypal.me/ErickAbrahamA ou em Jogo online > Doar. Obrigado!'),
 ('2026-11-20', 'fr', 'Soutenez LAIKA 64', 'LAIKA en a besoin : votre don paie les serveurs du jeu en ligne et les prochaines mises à jour. LAIKA 64 est et restera gratuit. Faites un don sur paypal.me/ErickAbrahamA ou dans Jeu en ligne > Faire un don. Merci !'),
 ('2026-11-20', 'it', 'Sostieni LAIKA 64', 'LAIKA ne ha bisogno: la tua donazione paga i server del gioco online e i prossimi aggiornamenti. LAIKA 64 è e resterà gratuito. Dona su paypal.me/ErickAbrahamA o in Gioco online > Dona. Grazie!'),
 ('2026-11-20', 'de', 'Unterstütze LAIKA 64', 'LAIKA braucht es: Deine Spende bezahlt die Online-Server und die nächsten Updates. LAIKA 64 ist und bleibt kostenlos. Spende über paypal.me/ErickAbrahamA oder unter Online-Spiel > Spenden. Danke!'),
 ('2026-11-20', 'ru', 'Поддержите LAIKA 64', 'LAIKA это нужно: ваше пожертвование оплачивает онлайн-серверы и следующие обновления. LAIKA 64 бесплатна и останется бесплатной. Пожертвовать: paypal.me/ErickAbrahamA или Игра по сети > Поддержать. Спасибо!');
